# 判定先手胜负
def nim_win(piles):
  s = 0
  for a in piles: s ^= a
  return s != 0

# 构造必胜走法：返回 (堆下标, 取走后该堆大小) 或 None
def nim_move(piles):
  s = 0
  for a in piles: s ^= a
  if s == 0: return None
  for i, a in enumerate(piles):
    if (a ^ s) < a:
      return (i, a ^ s)  # 从第 i 堆取走 a-(a^s) 枚
